#!/usr/bin/env python3
"""Build the static Italian and English pages; Python standard library only."""
from pathlib import Path
from html import escape
import json
ROOT = Path(__file__).resolve().parents[1]
DOMAIN = 'https://lytostudio.com'
SLUGS = {'it': {'home':'', 'web':'siti/', 'auto':'automazioni/', 'caller':'lyto-caller/'}, 'en': {'home':'', 'web':'websites/', 'auto':'automations/', 'caller':'lyto-caller/'}}
L = 'it'
def t(it,en): return it if L == 'it' else en
def url(key,lang=None):
    lang=lang or L
    return '/'+lang+'/'+SLUGS[lang][key]
def btn(label,href,primary=False): return f'<a class="btn {"btn-blue" if primary else "btn-ghost"}" href="{href}">{label} <span aria-hidden="true">→</span></a>'
def section(id,kicker,title,body,intro=''):
    return f'<section id="{id}"><div class="wrap"><span class="kicker">{kicker}</span><h2>{title}</h2>'+ (f'<p class="section-intro">{intro}</p>' if intro else '')+body+'</div></section>'
def lis(items): return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
def hero(kicker,title,description,visual,cta=None):
    return '<header class="hero"><div class="wrap"><div><span class="kicker">'+kicker+'</span><h1>'+title+'</h1><p class="lead">'+description+'</p><div class="ctas">'+btn(cta or t('Raccontaci cosa ti serve','Tell us what you need'),'#contact',True)+btn(t('Guarda un esempio','See an example'),'#example')+'</div><div class="trust">'+''.join('<span>'+x+'</span>' for x in [t('Costi definiti prima di iniziare','Costs agreed before we start'),t('Un referente dedicato','A dedicated contact'),t('Italiano e inglese','Italian and English')])+'</div></div>'+visual+'</div></header>'
def flow():
    steps=[(t('Arriva una richiesta','A request arrives'),t('Il cliente chiede informazioni o un preventivo.','A customer asks for information or a quote.')),(t('Le informazioni si organizzano','Information is organised'),t('Il sistema raccoglie i dati e prepara una bozza.','The system collects the details and prepares a draft.')),(t('Tu controlli e approvi','You check and approve'),t('Le azioni concordate restano sotto il tuo controllo.','The agreed actions remain under your control.'))]
    return '<aside class="flow"><p class="tag">'+t('Esempio illustrativo · automazione','Illustrative example · automation')+'</p><ol>'+''.join('<li><strong>'+a+'</strong><p>'+b+'</p></li>' for a,b in steps)+'</ol><p class="result">'+t('Una richiesta ordinata, pronta da seguire.','An organised request, ready to follow up.')+'</p><p class="example">'+t('Simulazione del flusso: le integrazioni vengono definite per ogni progetto.','Workflow simulation: integrations are defined for each project.')+'</p></aside>'
def work():
    return section('example',t('Un progetto reale','A real project'),t('Un progetto reale, <mark>da esplorare.</mark>','A website you can <mark>see for yourself.</mark>'),'<article class="work"><div class="browser"><div class="bar"><i></i><i></i><i></i><span>upcollectiontorino.com</span></div><img src="/assets/img/work-upcollection.webp" width="1000" height="625" loading="lazy" alt="'+t('Homepage del sito Up Collection','Up Collection website homepage')+'"></div><div><p class="label">'+t('Sito web · negozio di abbigliamento · Torino','Website · clothing store · Turin')+'</p><h3>Up Collection</h3><p>'+t('Un negozio di abbigliamento aperto dagli anni ’60. Abbiamo realizzato un sito per presentare le collezioni uomo e donna e facilitare il contatto con il negozio.','A clothing shop open since the 1960s. We built a website to present its women’s and men’s collections and make it easier to contact the shop.')+'</p><div class="chips"><span>IT / EN</span><span>Mobile</span><span>WhatsApp</span></div><p>'+t('Il lavoro: organizzazione delle pagine, versione italiana e inglese, contatto WhatsApp e configurazione di Google Search Console.','The work: page organisation, Italian and English versions, WhatsApp contact and Google Search Console setup.')+'</p><a class="btn btn-ghost" href="https://upcollectiontorino.com" target="_blank" rel="noopener">'+t('Visita il sito','Visit the website')+' ↗</a></div></article>')
def services():
    data=[('web',t('Un sito che presenta bene la tua attività','A website that presents your business clearly'),t('Servizi chiari, immagini e un percorso semplice per contattarti, anche dal telefono.','Clear services, images and a simple way to get in touch, including on mobile.'),t('Da 590 € una tantum','From €590 one-off')),
    ('auto',t('Meno operazioni ripetitive','Fewer repetitive tasks'),t('Colleghiamo gli strumenti che usi e automatizziamo un processo concreto: richieste, dati o preparazione dei preventivi.','We connect the tools you use and automate one specific process: requests, data or quote preparation.'),t('Da 1.490 € + gestione da 99 €/mese','From €1,490 + management from €99/month')),
    ('caller',t('La tua agenzia continua a rispondere','Your agency keeps answering'),t('Lyto Caller raccoglie le richieste telefoniche quando sei impegnato e ti invia un riepilogo per richiamare.','Lyto Caller collects phone enquiries while you are busy and sends a summary so you can call back.'),t('149 €/mese + 290 € di attivazione','€149/month + €290 setup'))]
    return section('services',t('Scegli da dove partire','Choose where to start'),t('Quale problema vuoi <mark>risolvere?</mark>','What would you like to <mark>solve?</mark>'),'<div class="svcs">'+''.join('<article class="svc"><div class="n">0'+str(i+1)+'</div><h3>'+a+'</h3><p>'+b+'</p><p class="from">'+c+'</p>'+btn(t('Scopri il servizio','Explore the service'),url(k))+'</article>' for i,(k,a,b,c) in enumerate(data))+'</div><p class="price-note">'+tax()+'</p>')
def tax(): return t('Importi IVA esclusa, se applicabile. Inclusioni e costi ricorrenti sono indicati nelle pagine dei servizi.','Prices exclude VAT where applicable. Inclusions and recurring costs are listed on each service page.')
def process():
    rows=[(t('Ci racconti come lavori','Tell us how you work'),t('In 20 minuti guardiamo il problema, gli strumenti che utilizzi e il risultato che cerchi.','In 20 minutes we discuss the problem, the tools you use and what you want to achieve.')),(t('Ricevi una proposta precisa','Get a clear proposal'),t('Attività incluse, esclusioni, prezzo, canoni e data di consegna. Gli extra si concordano prima.','Scope, exclusions, price, recurring fees and delivery date. Extra work is agreed in advance.')),(t('Proviamo la soluzione insieme','Test the solution together'),t('Verifichiamo i casi concordati, ti mostriamo come usarla e definiamo l’assistenza successiva.','We test the agreed cases, show you how to use it and define ongoing support.'))]
    return section('how',t('Come lavoriamo','How we work'),t('Prima capiamo il problema. <mark>Poi costruiamo.</mark>','First we understand the problem. <mark>Then we build.</mark>'),'<div class="steps">'+''.join('<article class="step"><span class="k">0'+str(i+1)+'</span><h3>'+a+'</h3><p>'+b+'</p></article>' for i,(a,b) in enumerate(rows))+'</div>')
def team():
    rows=[('erica','Erica',t('Il tuo riferimento in italiano. Raccoglie le esigenze, chiarisce i passaggi e segue il progetto fino alla consegna.','Your Italian-speaking contact. She gathers requirements, explains the steps and follows your project through to delivery.')),('abdo','Abdo',t('Si occupa dello sviluppo dei siti, delle integrazioni e dei sistemi AI. Lavora in inglese.','He develops websites, integrations and AI systems. He works in English.'))]
    return section('team',t('Con chi lavori','Who you work with'),t('Due persone. <mark>Responsabilità chiare.</mark>','Two people. <mark>Clear responsibilities.</mark>'),'<div class="team">'+''.join('<article class="mate"><img src="/assets/img/'+img+'.webp" width="150" height="150" loading="lazy" alt="'+name+'"><div><h3>'+name+'</h3><p>'+desc+'</p></div></article>' for img,name,desc in rows)+'</div>')
def contact(key):
    topic={'home':'unsure','web':'website','auto':'automation','caller':'caller'}[key]
    options=[('unsure',t('Vorrei un consiglio','I would like advice')),('website',t('Un sito web','A website')),('automation',t('Un’automazione o un assistente AI','An automation or AI assistant')),('caller',t('Una demo di Lyto Caller','A Lyto Caller demo'))]
    return '<section id="contact"><div class="wrap"><div class="final"><span class="kicker">'+t('Partiamo da una conversazione','Start with a conversation')+'</span><h2>'+t(('Proviamo Caller sulla <mark>tua agenzia.</mark>' if key=='caller' else 'Raccontaci cosa vuoi <mark>semplificare.</mark>'),('Try Caller for <mark>your agency.</mark>' if key=='caller' else 'Tell us what you want to <mark>simplify.</mark>'))+'</h2><p class="lead">'+t('Non serve conoscere la tecnologia. Descrivici la tua attività e il problema che vuoi risolvere. La prima chiamata di 20 minuti è gratuita.','You do not need technical knowledge. Tell us about your business and the problem you want to solve. The first 20-minute call is free.')+'</p><div class="ctas">'+btn(t('Prenota sul calendario','Book on our calendar'),'https://cal.com/lyto-studio/20min',True)+'</div><p class="contact-note">'+t('Si apre Cal.com, il servizio esterno di prenotazione. Preferisci scriverci? Prepara un’email qui sotto.','Opens Cal.com, our external booking service. Prefer to write? Prepare an email below.')+'</p><form class="cform" id="cform"><div class="row"><label>'+t('Nome','Name')+'<input name="name" required autocomplete="name" maxlength="120"></label><label>Email<input name="email" type="email" required autocomplete="email" maxlength="254"></label></div><label>'+t('Cosa ti interessa?','What are you interested in?')+'<select name="topic">'+''.join('<option value="'+v+'"'+(' selected' if v==topic else '')+'>'+label+'</option>' for v,label in options)+'</select></label><label>'+t('La tua attività e cosa vorresti migliorare','Your business and what you want to improve')+'<textarea name="message" rows="4" required maxlength="4000"></textarea></label><p class="fine">'+t('Il modulo prepara un’email nella tua app di posta: dovrai inviarla da lì. I dati non vengono inviati automaticamente dal sito.','This form prepares an email in your mail app: you will need to send it there. The website does not send the details automatically.')+' <a href="/privacy.html?lang='+L+'">'+t('Informativa privacy','Privacy policy')+'</a></p><button class="btn btn-blue" type="submit">'+t('Prepara l’email','Prepare email')+' →</button><p id="fmsg" class="fmsg" role="status" aria-live="polite"></p><p class="fine">'+t('Nessuna app email configurata? Scrivi direttamente a','No mail app configured? Write directly to')+' <a href="mailto:hello@lytostudio.com">hello@lytostudio.com</a>.</p></form></div></div></section>'
def faq(rows):
    return section('faq',t('Prima di decidere','Before you decide'),t('Le risposte che <mark>ti servono.</mark>','The answers <mark>you need.</mark>'),'<div class="faq">'+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in rows)+'</div>')
def general_faq():
    return faq([(t('Devo sapere qualcosa di tecnico?','Do I need technical knowledge?'),t('No. Partiamo da come lavori oggi, ti spieghiamo la proposta in modo chiaro e ti mostriamo come usare la soluzione.','No. We start with how you work today, explain the proposal clearly and show you how to use the solution.')),(t('Il prezzo può cambiare durante il progetto?','Can the price change during the project?'),t('Il prezzo concordato copre le attività scritte nella proposta. Se chiedi nuove funzionalità, ne definiamo costo e tempi prima di procedere.','The agreed price covers the work in the proposal. If you request new features, we agree their cost and timing before proceeding.')),(t('Lavorate solo a Torino?','Do you only work in Turin?'),t('Siamo a Torino e lavoriamo anche da remoto, in italiano e inglese.','We are based in Turin and also work remotely, in Italian and English.'))])
def plan(name,price,when,items,cta,hot=False):
    return '<article class="plan'+(' hot' if hot else '')+'"><h3 class="nm">'+name+'</h3><p class="pr">'+price+'</p><p class="when">'+when+'</p>'+lis(items)+btn(cta,'#contact',hot)+'</article>'
def web_prices():
    essentials=[t('Una pagina, fino a 6 sezioni','One page, up to 6 sections'),t('Una lingua','One language'),t('Layout per telefono e computer','Mobile and desktop layout'),t('Modulo email, contatti e mappa','Email form, contact details and map'),t('Impostazioni SEO essenziali','Essential SEO setup'),t('Due cicli di revisione','Two revision rounds')]
    business=[t('Fino a 5 pagine, una lingua','Up to 5 pages, one language'),t('Organizzazione dei contenuti','Content organisation'),t('Revisione dei testi forniti','Editing of supplied copy'),t('Modulo per richieste o preventivi','Enquiry or quote request form'),t('Impostazioni SEO essenziali','Essential SEO setup'),t('Due cicli di revisione','Two revision rounds')]
    return section('pricing',t('Pacchetti e inclusioni','Packages and inclusions'),t('Sai cosa spendi <mark>prima di iniziare.</mark>','Know what you spend <mark>before we start.</mark>'),'<div class="plans two">'+plan(t('Essenziale','Essential'),t('590 €','€590'),t('Una tantum · per presentarti in una pagina','One-off · introduce your business on one page'),essentials,t('Parliamo del tuo sito','Discuss your website'))+plan('Business',t('1.290 €','€1,290'),t('Una tantum · più spazio ai tuoi servizi','One-off · more room for your services'),business,t('Richiedi una proposta','Request a proposal'),True)+'</div><aside class="optional"><h3>'+t('Cura del sito · 49 €/mese, facoltativa','Website care · €49/month, optional')+'</h3><p>'+t('Hosting, rinnovo di un dominio standard, controlli e fino a 30 minuti di modifiche ai contenuti al mese, non cumulabili. Nuove pagine e funzionalità si quotano a parte. Se non scegli la gestione, concordiamo hosting, consegna e relativi costi nella proposta.','Hosting, one standard domain renewal, checks and up to 30 minutes of content changes per month, which do not roll over. New pages and features are quoted separately. Without care, hosting, handover and related costs are agreed in the proposal.')+'</p></aside><p class="price-note">'+t('Materiali e immagini forniti dal cliente. Fotografie, traduzioni, e-commerce, servizi esterni a pagamento e integrazioni personalizzate esclusi. La data di consegna viene concordata dopo aver verificato i materiali. IVA esclusa, se applicabile.','Client supplies source materials and images. Photography, translations, e-commerce, paid external services and custom integrations are excluded. Delivery date is agreed after reviewing materials. VAT excluded where applicable.')+'</p>')
def auto_prices():
    items=[t('Un processo definito nella proposta','One process defined in the proposal'),t('Fino a 2 strumenti collegati','Up to 2 connected tools'),t('Configurazione, test e passaggio operativo','Configuration, testing and handover'),t('Primo mese di gestione incluso','First month of management included')]
    return section('pricing',t('Realizzazione e gestione','Build and ongoing management'),t('Un processo preciso. <mark>Un costo chiaro.</mark>','One defined process. <mark>Clear costs.</mark>'),'<div class="plans two">'+plan(t('Realizzazione','Build'),t('Da 1.490 €','From €1,490'),t('Una tantum + gestione da 99 €/mese dal secondo mese','One-off + management from €99/month from month two'),items,t('Analizziamo il tuo processo','Discuss your process'),True)+'<article class="plan"><h3 class="nm">'+t('Cosa comprende la gestione','What management covers')+'</h3><p>'+t('Infrastruttura, monitoraggio, costi AI entro i volumi concordati e correzioni del flusso realizzato.','Infrastructure, monitoring, AI costs within agreed usage and fixes to the delivered workflow.')+'</p>'+lis([t('Volumi e consumi inclusi scritti nella proposta','Included usage written in the proposal'),t('Costi extra e soglie definiti prima dell’avvio','Extra costs and limits defined before launch'),t('Nuovi flussi e funzioni quotati separatamente','New workflows and features quoted separately')])+'<p>'+t('Per il progetto base, 12 mesi dall’avvio partono da 2.579 €: 1.490 € + 11 canoni da 99 €.','For the base project, the first 12 months start at €2,579: €1,490 + 11 payments of €99.')+'</p></article></div><p class="price-note">'+t('Canone necessario per il sistema gestito da noi. Licenze dei tuoi strumenti ed eventuali servizi aggiuntivi sono specificati nel preventivo. Durata, recesso, volumi e assistenza vengono definiti nella proposta. IVA esclusa, se applicabile.','The management fee is required for the system we operate. Your software licences and any additional services are specified in the quote. Term, cancellation, usage and support are defined in the proposal. VAT excluded where applicable.')+'</p>')
def auto_example():
    return section('example',t('Esempio illustrativo','Illustrative example'),t('Da una richiesta sparsa a <mark>una bozza da approvare.</mark>','From a scattered request to <mark>a draft for approval.</mark>'),'<div class="comparison"><div><h3>'+t('Prima','Before')+'</h3><p>'+t('Leggi l’email, copi i dati, cerchi il listino, prepari il preventivo e aggiorni il foglio delle richieste.','Read the email, copy the details, look up the price list, prepare the quote and update the enquiries spreadsheet.')+'</p></div><div><h3>'+t('Con il flusso concordato','With the agreed workflow')+'</h3><p>'+t('Il sistema estrae i dati dalla richiesta, segnala le informazioni mancanti, prepara una bozza dal listino e la presenta per la tua approvazione.','The system extracts the enquiry details, flags missing information, drafts a quote from the price list and presents it for your approval.')+'</p></div></div><p class="price-note">'+t('Simulazione, non un risultato misurato su un cliente. Compatibilità, regole e approvazioni vengono verificate prima della proposta.','A simulation, not a measured client result. Compatibility, rules and approvals are checked before the proposal.')+'</p>')
def caller_visual():
    return '<aside class="flow"><p class="tag">'+t('Lyto Caller · esempio illustrativo','Lyto Caller · illustrative example')+'</p><div class="call-script"><p><strong>Caller</strong><br>'+t('«Buongiorno, sono l’assistente virtuale dell’agenzia. Come posso aiutarti?»','“Hello, I am the agency’s virtual assistant. How can I help?”')+'</p><p><strong>'+t('Cliente','Customer')+'</strong><br>'+t('«Cerco un trilocale in affitto a Torino.»','“I am looking for a two-bedroom rental in Turin.”')+'</p><p><strong>Caller</strong><br>'+t('«In quale zona e con quale budget? Posso raccogliere un recapito per farti richiamare?»','“Which area and budget? May I take a contact number so the team can call you back?”')+'</p></div><div class="summary-box">'+t('Riepilogo per l’agenzia: richiesta affitto · trilocale · zona, budget e recapito raccolti durante la conversazione.','Agency summary: rental enquiry · two bedrooms · area, budget and contact details collected during the conversation.')+'</div><p class="example">'+t('Conversazione simulata. Per ascoltare il sistema, richiedi una demo.','Simulated conversation. Request a demo to hear the system.')+'</p></aside>'
def caller_prices():
    return section('pricing',t('Un piano semplice','One simple plan'),t('Attivazione e utilizzo, <mark>senza ambiguità.</mark>','Setup and usage, <mark>clearly explained.</mark>'),'<div class="plans two">'+plan('Lyto Caller',t('149 €<small>/mese + 290 € di attivazione</small>','€149<small>/month + €290 setup</small>'),t('Una sede · un numero collegato','One office · one connected number'),[t('300 minuti al mese inclusi','300 minutes per month included'),t('Minuti aggiuntivi: 0,30 €/min','Additional minutes: €0.30/min'),t('Raccolta delle informazioni concordate','Collection of agreed enquiry details'),t('Riepilogo delle richieste su WhatsApp','Enquiry summaries on WhatsApp'),t('Configurazione e test iniziali','Initial setup and testing')],t('Richiedi una demo','Request a demo'),True)+'<article class="plan"><h3 class="nm">'+t('Quanto spendi in concreto?','What does it cost in practice?')+'</h3><p>'+t('Primo mese, entro 300 minuti: <strong>439 €</strong>, inclusa l’attivazione.','First month, within 300 minutes: <strong>€439</strong>, including setup.')+'</p><p>'+t('Mesi successivi, entro 300 minuti: <strong>149 €/mese</strong>.','Following months, within 300 minutes: <strong>€149/month</strong>.')+'</p><p>'+t('Con 450 minuti in un mese: 149 € + 150 × 0,30 € = <strong>194 €</strong>, oltre all’attivazione se è il primo mese.','With 450 minutes in a month: €149 + 150 × €0.30 = <strong>€194</strong>, plus setup if it is the first month.')+'</p><p>'+t('Più sedi, più numeri e integrazioni aggiuntive: proposta dedicata.','Additional offices, numbers and integrations: custom proposal.')+'</p></article></div><p class="price-note">'+t('Nessun piano annuale obbligatorio. Preavviso di cancellazione, decorrenza e conteggio dei minuti vengono specificati nella proposta. Eventuali costi di deviazione del tuo operatore telefonico sono esclusi. IVA esclusa, se applicabile.','No mandatory annual plan. Cancellation notice, start date and minute accounting are specified in the proposal. Any call-forwarding charges from your phone provider are excluded. VAT excluded where applicable.')+'</p>')
def body(key):
    if key=='home':
        return hero(t('Siti web · Automazioni · Assistenti AI','Websites · Automations · AI assistants'),t('Meno lavoro ripetitivo.<br><mark>Più spazio per i tuoi clienti.</mark>','Less repetitive work.<br><mark>More room for your customers.</mark>'),t('Aiutiamo piccole attività e professionisti a presentarsi meglio online, organizzare le richieste e ridurre le operazioni manuali. Partiamo dal problema e scegliamo gli strumenti adatti.','We help small businesses and professionals present themselves online, organise enquiries and reduce manual tasks. We start with the problem and choose the right tools.'),flow())+services()+work()+process()+team()+general_faq()+contact(key)
    if key=='web':
        visual='<div class="browser"><div class="bar"><span>upcollectiontorino.com</span></div><img src="/assets/img/work-upcollection.webp" width="1000" height="625" alt="'+t('Sito Up Collection realizzato da Lyto','Up Collection website built by Lyto')+'"><p class="term-note">'+t('Un progetto reale di Lyto Studio','A real Lyto Studio project')+'</p></div>'
        return hero(t('Siti per piccole attività','Websites for small businesses'),t('Fai capire cosa offri.<br><mark>Rendi semplice contattarti.</mark>','Make your offer clear.<br><mark>Make getting in touch easy.</mark>'),t('Un sito per negozi, studi e professionisti: servizi chiari, contenuti ordinati e contatti a portata di mano. Progettato per chi ti cerca dal telefono.','A website for shops, practices and professionals: clear services, organised content and easy contact. Designed for people finding you on their phones.'),visual)+work()+web_prices()+process()+faq([(t('Cosa devo fornire?','What do I need to supply?'),t('Logo, immagini utilizzabili, informazioni sull’attività e testi di partenza. Nel pacchetto Business organizziamo i contenuti e revisioniamo i testi forniti.','Your logo, usable images, business information and draft copy. Business includes content organisation and editing of supplied text.')),(t('Il sito sarà primo su Google?','Will the website rank first on Google?'),t('Non promettiamo posizioni. Le impostazioni SEO essenziali rendono le pagine comprensibili ai motori di ricerca; visibilità e risultati dipendono anche da contenuti, concorrenza e attività successive.','We do not promise rankings. Essential SEO helps search engines understand the pages; visibility and results also depend on content, competition and ongoing work.')),(t('Posso aggiungere un’altra lingua o prenotazioni?','Can I add another language or booking features?'),t('Sì, li valutiamo nella proposta. Traduzioni, prenotazioni con logiche personalizzate e strumenti esterni a pagamento non sono inclusi automaticamente nei pacchetti.','Yes, we assess them in the proposal. Translations, custom booking logic and paid external tools are not automatically included.'))])+contact(key)
    if key=='auto':
        return hero(t('Automazioni e assistenti AI','Automations and AI assistants'),t('Gli stessi dati, tre programmi?<br><mark>Colleghiamo i passaggi.</mark>','The same details in three tools?<br><mark>Connect the steps.</mark>'),t('Analizziamo un processo ripetitivo e realizziamo un flusso su misura. Richieste organizzate, bozze da approvare e meno copia-incolla tra gli strumenti che utilizzi.','We analyse a repetitive process and build a workflow around it. Organised enquiries, drafts for approval and less copying between the tools you use.'),flow())+auto_example()+auto_prices()+process()+faq([(t('Serve davvero l’intelligenza artificiale?','Does it always need AI?'),t('Non sempre. Usiamo regole e collegamenti semplici quando bastano. L’AI entra dove serve interpretare richieste o preparare contenuti, con controlli definiti insieme.','Not always. We use simple rules and connections where they are enough. AI helps interpret requests or draft content, with checks agreed together.')),(t('E se l’AI sbaglia?','What if the AI makes a mistake?'),t('Può succedere. Definiamo quali azioni richiedono approvazione, come segnalare dati mancanti e quando passare la richiesta a una persona. Un’automazione non elimina la necessità di controllo.','It can happen. We define which actions need approval, how to flag missing information and when to hand a request to a person. Automation does not eliminate the need for oversight.')),(t('Quali strumenti potete collegare?','Which tools can you connect?'),t('Verifichiamo accessi, API e limiti degli strumenti durante l’analisi. Nessuna compatibilità viene data per scontata; licenze e costi esterni vengono indicati nella proposta.','We check access, APIs and tool limits during discovery. Compatibility is never assumed; external licences and costs are listed in the proposal.'))])+contact(key)
    return hero(t('Per agenzie immobiliari','For real estate agencies'),t('Quando sei in visita,<br><mark>la tua agenzia continua a rispondere.</mark>','While you are at a viewing,<br><mark>your agency keeps answering.</mark>'),t('Lyto Caller è l’assistente vocale AI che raccoglie le richieste di chi cerca, vende o affitta un immobile e ti invia un riepilogo per richiamare con le informazioni utili.','Lyto Caller is the AI voice assistant that collects enquiries from people buying, selling or renting and sends a summary with the details you need to call back.'),caller_visual(),t('Richiedi una demo','Request a demo'))+section('example',t('Prima di attivarlo','Before activation'),t('Ascoltalo. Provalo. <mark>Decidi con chiarezza.</mark>','Hear it. Try it. <mark>Decide with clarity.</mark>'),'<div class="comparison"><div><h3>'+t('Una demo sulla tua attività','A demo for your business')+'</h3><p>'+t('Ci racconti che richieste ricevi. Nella dimostrazione verifichiamo tono, domande e riepilogo. Ti mostriamo anche come gestire le richieste che necessitano di una persona.','Tell us what enquiries you receive. In the demonstration we review the tone, questions and summary, including how to handle requests that need a person.')+'</p></div><div><h3>'+t('Attivazione dopo i test','Activation after testing')+'</h3><p>'+t('Prepariamo informazioni, regole e recapiti. Concordiamo tempi e configurazione della deviazione, poi proviamo i casi previsti prima di attivare il servizio.','We prepare information, rules and contact details. We agree timing and call-forwarding setup, then test the expected cases before activating the service.')+'</p></div></div>')+caller_prices()+faq([(t('Devo cambiare numero?','Do I need to change my number?'),t('La configurazione prevista usa la deviazione di chiamata. Verifichiamo prima la compatibilità e gli eventuali costi del tuo operatore.','The planned configuration uses call forwarding. We check compatibility and any charges from your phone provider first.')),(t('Cosa succede se non conosce una risposta?','What happens if it does not know an answer?'),t('Definiamo le informazioni utilizzabili e i casi da passare all’agenzia. Il flusso previsto raccoglie il recapito per un richiamo, senza promettere disponibilità o condizioni non confermate.','We define the information it can use and the cases to pass to the agency. The planned workflow collects a callback number without promising unconfirmed availability or terms.')),(t('Può fissare appuntamenti e leggere gli annunci?','Can it book appointments and use property listings?'),t('Dipende dagli strumenti dell’agenzia. Calendari, annunci e integrazioni vengono verificati e quotati nella proposta; non sono inclusi automaticamente nel piano base.','It depends on your agency’s tools. Calendars, listings and integrations are checked and quoted in the proposal; they are not automatically included in the base plan.')),(t('Posso ascoltare una registrazione qui?','Can I listen to a recording here?'),t('In questa pagina mostriamo una conversazione simulata scritta. Richiedi una demo per ascoltare e provare il sistema prima di decidere.','This page shows a written simulated conversation. Request a demo to hear and try the system before deciding.'))])+contact(key)
TITLES={'home':('Siti web e automazioni per piccole attività','Websites and automations for small businesses'),'web':('Siti web per attività e professionisti · da 590 €','Websites for small businesses · from €590'),'auto':('Automazioni e assistenti AI · costi e inclusioni','Automations and AI assistants · pricing and scope'),'caller':('Lyto Caller · Assistente telefonico per agenzie immobiliari','Lyto Caller · AI phone assistant for real estate agencies')}
def render(key):
    title='Lyto Studio · '+t(*TITLES[key]) if key!='caller' else t(*TITLES[key])
    desc={'home':t('Siti web, automazioni e assistenti AI per piccole attività. Da Torino, in italiano e inglese. Scopri esempi, prezzi e inclusioni.','Websites, automations and AI assistants for small businesses. Based in Turin, working in English and Italian. Explore examples, pricing and scope.'),'web':t('Siti web da 590 €, fino a 5 pagine a 1.290 €. Pacchetti chiari, manutenzione facoltativa e un progetto reale da vedere.','Websites from €590, up to 5 pages for €1,290. Clear packages, optional care and a real project to explore.'),'auto':t('Automatizza un processo ripetitivo. Realizzazione da 1.490 € e gestione da 99 €/mese, con volumi e controlli concordati.','Automate one repetitive process. Build from €1,490 and management from €99/month, with agreed usage and oversight.'),'caller':t('Lyto Caller raccoglie le richieste telefoniche della tua agenzia. 149 €/mese e 290 € di attivazione, 300 minuti inclusi. Richiedi una demo.','Lyto Caller collects your agency’s phone enquiries. €149/month and €290 setup, with 300 minutes included. Request a demo.')}[key]
    navkeys=[('web',t('Siti web','Websites')),('auto',t('Automazioni','Automations')),('caller','Lyto Caller')]
    nav=''.join('<a href="'+url(k)+'"'+(' aria-current="page"' if k==key else '')+'>'+label+'</a>' for k,label in navkeys)
    if key != 'home':
        nav += '<a href="#pricing">'+t('Prezzi','Pricing')+'</a>'
    schema={'@context':'https://schema.org','@type':'ProfessionalService','name':'Lyto Studio','url':DOMAIN,'email':'hello@lytostudio.com','address':{'@type':'PostalAddress','addressLocality':'Torino','addressCountry':'IT'},'availableLanguage':['it','en']}
    content = body(key)
